// Dynamic variables ($guid, $timestamp, $random*, ...) generated by our own logic, no
// faker dependency. A {{$name}} placeholder resolves to a fresh value per occurrence.
// Isomorphic: no node imports.

export interface DynamicVariable {
  name: string;
  description: string;
  example: string;
}

const rnd = (maxExclusive: number): number => Math.floor(Math.random() * maxExclusive);
const between = (min: number, maxExclusive: number): number => min + rnd(maxExclusive - min);
const pick = <T>(pool: readonly T[]): T => pool[rnd(pool.length)];
const randomString = (alphabet: string, length: number): string =>
  Array.from({ length }, () => alphabet[rnd(alphabet.length)]).join("");
const capitalize = (s: string): string => (s ? s[0].toUpperCase() + s.slice(1) : s);
const times = <T>(n: number, fn: () => T): T[] => Array.from({ length: n }, fn);

function uuid(): string {
  const c = (globalThis as { crypto?: { randomUUID?: () => string } }).crypto;
  if (c?.randomUUID) return c.randomUUID();
  const hex = randomString("0123456789abcdef", 32).split("");
  hex[12] = "4";
  hex[16] = "89ab"[rnd(4)];
  const h = hex.join("");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

/** Local date in the `Wed Oct 01 2026 22:40:00 GMT+0530` style. */
function jsDate(d: Date): string {
  return d.toString().replace(/\s*\(.*\)\s*$/, "");
}

