const GENERATORS = new Map<string, () => string>(DEFINITIONS.map(([name, , gen]) => [name.toLowerCase(), gen]));

function example(gen: () => string): string {
  try {
    const s = gen();
    return s.length > 48 ? s.slice(0, 48) + "..." : s;
  } catch {
    return "";
  }
}

/** The full catalog in display order, for autocomplete and hover hints. */
export const DYNAMIC_VARIABLES: DynamicVariable[] = DEFINITIONS.map(([name, description, gen]) => ({
  name,
  description,
  example: example(gen),
}));

const CATALOG = new Map(DYNAMIC_VARIABLES.map((d) => [d.name.toLowerCase(), d]));

/** True if `name` (placeholder body, e.g. `$guid`) is a known dynamic variable. Case-insensitive. */
export function isDynamicVariable(name: string | undefined | null): boolean {
  return !!name && GENERATORS.has(name.trim().toLowerCase());
}

export function findDynamicVariable(name: string | undefined | null): DynamicVariable | undefined {
  return name ? CATALOG.get(name.trim().toLowerCase()) : undefined;
}

/** Generates a fresh value, or undefined if the name is not a dynamic variable. */
export function tryGenerate(name: string | undefined | null): string | undefined {
  if (!name) return undefined;
  const gen = GENERATORS.get(name.trim().toLowerCase());
  if (!gen) return undefined;
  try {
    return gen();
  } catch {
    return undefined;
  }
}
